struct aiocb cb; memset(&cb, 0, sizeof cb);
cb.aio_fildes = fd; cb.aio_buf = buf; cb.aio_nbytes = n;
cb.aio_sigevent.sigev_notify = SIGEV_THREAD;
cb.aio_sigevent.sigev_notify_function = on_done;
cb.aio_sigevent.sigev_value.sival_ptr = conn;   /* the ACT rides with the op */
