struct iocb cb = {0}; struct iocb *cbs[1] = { &cb };
cb.aio_fildes = fd; cb.aio_lio_opcode = IOCB_CMD_PREAD;
cb.aio_buf = (__u64) buf; cb.aio_nbytes = n;
cb.aio_data = (__u64) req_id;          /* the ACT, opaque to the kernel */
io_submit(ctx, 1, cbs);
struct io_event ev[1];
io_getevents(ctx, 1, 1, ev, NULL);
dispatch((uint64_t) ev[0].data);       /* token comes back with the completion */

